.xt-root * { box-sizing: border-box !important; }
.xt-header, .xt-badge, .xt-grid, .xt-section, .xt-toggle, .xt-action-1, .xt-action-2 { display: none !important; }
.xt-text { 
    margin: 0 !important; padding: 0 !important; border: none !important; 
    display: block !important; box-shadow: none !important; 
    white-space: pre-wrap !important; outline: none !important; 
    background: transparent !important; border-radius: 0 !important; 
}

.xt-root {
    position: relative !important;
    width: 100% !important; max-width: 400px !important;
    height: 700px !important;
    margin: 0 auto !important;
    background-color: #e8e8e8 !important;
    z-index: 0 !important;
    overflow: hidden !important;
    border-radius: 0 !important;
}

.xt-root::before {
    content: '' !important;
    position: absolute !important;
    top: 70px !important; left: 10px !important; right: 10px !important; bottom: 10px !important;
    background: #ffffff !important;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08) !important;
    z-index: -1 !important;
}

.xt-root::after {
    content: '' !important;
    position: absolute !important;
    top: 60px !important; left: 10px !important; right: 10px !important; height: 30px !important;
    background-image: 
        radial-gradient(circle at 20px 22px, #e8e8e8 6px, transparent 6px),
        linear-gradient(to right, transparent 17px, #e8e8e8 17px, #e8e8e8 23px, transparent 23px) !important;
    background-size: 40px 30px, 40px 22px !important;
    background-repeat: repeat-x !important;
    z-index: 0 !important;
}

